def resolve(week, lesson):
    n = int(lesson)
    local = n if week == 1 else n - (20 if week == 2 else 30)
    folder = glob.glob(os.path.join(PL, f"week {week}", f"{local}. *"))[0]
    lines = open(os.path.join(folder, "index.vtt"), encoding="utf-8").read().splitlines()
    transcript = " ".join(line for line in lines if line and line != "WEBVTT"
                          and not line.startswith("NOTE ") and "-->" not in line)
    return TOPICS[n], norm(transcript)


